def is_sidon(S, offdiag_only):
    d = {}
    n = len(S)
    for i in range(n):
        for j in range(i, n):
            if offdiag_only and i == j:
                continue
            s = S[i] + S[j]
            if s in d:
                a, b = d[s]
                if sorted((a, b)) != sorted((S[i], S[j])):
                    return False
            else:
                d[s] = (S[i], S[j])
    return True

def F(N, offdiag_only):
    def rec(start, chosen):
        if not is_sidon(chosen, offdiag_only):
            return 0
        best = len(chosen)
        for x in range(start, N + 1):
            chosen.append(x)
            v = rec(x + 1, chosen)
            if v > best:
                best = v
            chosen.pop()
        return best
    return rec(1, [])

def verify(witness):
    lo = witness['range'][0]
    hi = witness['range'][1]
    if lo != 1:
        raise ValueError('range must start at 1')
    if hi < 24:
        raise ValueError('range must cover N=1..24')
    vals = {}
    for N in range(1, hi + 1):
        f_all = F(N, False)
        f_off = F(N, True)
        if f_all != f_off:
            raise ValueError('convention mismatch at N=%d' % N)
        vals[N] = f_all
    for N in range(1, hi):
        if vals[N + 1] > vals[N] + 1:
            raise ValueError('removal bound fails at N=%d' % N)
    if vals[2] != vals[1] + 1:
        raise ValueError('sharpness fails at N=1')
    if vals[4] != vals[3] + 1:
        raise ValueError('sharpness fails at N=3')
    return True
